// Golden vectors from crates/bunker-core/vectors/ (generated by the Rust encoder), re-checked
// through the WASM build and the TypeScript mirror.
import { beforeAll, describe, expect, it } from 'vitest';
import { readFileSync } from 'node:fs';
import { PublicKey } from '@solana/web3.js';
import { hkdf } from '@noble/hashes/hkdf.js';
import { pbkdf2 } from '@noble/hashes/pbkdf2.js';
import { sha256, sha512 } from '@noble/hashes/sha2.js';
import { initWasm, getWasm } from '../src/wasm';
import { deriveRoot, keyBinding, validateMnemonic, vaultFromSeed, vaultKeyContext } from '../src/keys';
import type { KeyContext } from '../src/keys';
import { actionsFromJson, decodeActions, decodeActionsTs, encodeActions, encodeActionsTs, messagePrefixTs, parseMessage } from '../src/actions';
import { computeVaultId, encodeOptions, findStatePda, findWalletPda } from '../src/addresses';
import { concatBytes, fromHex, toHex, u32le, utf8 } from '../src/bytes';
import { CLUSTER_ID, PROGRAM_ID } from '../src/constants';
import type { ClusterName } from '../src/constants';

const dir = new URL('../../../crates/bunker-core/vectors/', import.meta.url);
const load = <T>(f: string): T => JSON.parse(readFileSync(new URL(f, dir), 'utf8')) as T;

interface ActionsVectors {
  valid: { name: string; actions: unknown[]; payload: string }[];
  invalid: { name: string; payload: string; error: string }[];
}
interface KeyEpochVector {
  name: string;
  epoch: number;
  cluster: number;
  program_id: string;
  /** options_v1 at epoch 0, vault_id at epoch ≥ 1 (MESSAGE_FORMAT §2). */
  binding: string;
  info: string;
  lms_seed: string;
  lms_i: string;
  root: string;
}
interface KeysVectors {
  mnemonic: string;
  seed64: string;
  hkdf_salt: string;
  epochs: KeyEpochVector[];
  generate_mnemonic: { entropy: string; mnemonic: string }[];
}
interface MessagesVectors {
  messages: {
    name: string;
    cluster: number;
    program_id: string;
    tag: number;
    vault_state: string;
    root_epoch: number;
    leaf_index: number;
    payload: string;
    prefix: string;
    message: string;
  }[];
}
interface SignaturesVectors {
  signatures: {
    name: string;
    epoch: number;
    leaf_index: number;
    cluster: number;
    binding: string;
    message: string;
    root: string;
    signature: string;
  }[];
}
interface VaultIdVectors {
  program_id: string;
  vaults: {
    name: string;
    root: string;
    cosigner: string | null;
    options: string;
    vault_id: string;
    state: string;
    state_bump: number;
    wallet: string;
    wallet_bump: number;
  }[];
}

const actions = load<ActionsVectors>('actions.json');
const keys = load<KeysVectors>('keys.json');
const messages = load<MessagesVectors>('messages.json');
const signatures = load<SignaturesVectors>('signatures.json');
const vaultIds = load<VaultIdVectors>('vault_ids.json');

const CLUSTER_BY_ID = new Map(Object.entries(CLUSTER_ID).map(([name, id]) => [id, name as ClusterName]));
function clusterName(id: number): ClusterName {
  const c = CLUSTER_BY_ID.get(id);
  if (!c) throw new Error(`vector uses cluster ${id}, which the SDK does not support`);
  return c;
}

/** The SDK key context a vector's (epoch, cluster, program, binding) stands for. */
function ctxOf(v: { epoch: number; cluster: number; binding: string }, programId: PublicKey = PROGRAM_ID): KeyContext {
  const cluster = clusterName(v.cluster);
  const b = fromHex(v.binding);
  if (v.epoch > 0) return { cluster, programId, vaultId: b };
  // options_v1 = u8(1) ‖ u8(has_cosigner) ‖ [cosigner (32)]
  expect(b[0]).toBe(1);
  return { cluster, programId, cosigner: b[1] === 1 ? new PublicKey(b.subarray(2)) : null };
}

beforeAll(async () => {
  await initWasm();
  await initWasm(); // idempotent
});

describe('golden vectors: actions', () => {
  for (const v of actions.valid) {
    it(`encodes ${v.name}`, () => {
      const parsed = actionsFromJson(JSON.stringify(v.actions));
      expect(toHex(encodeActions(parsed))).toBe(v.payload);
      expect(toHex(encodeActionsTs(parsed))).toBe(v.payload);
      const decoded = decodeActions(fromHex(v.payload));
      expect(toHex(encodeActionsTs(decoded))).toBe(v.payload);
      expect(toHex(encodeActionsTs(decodeActionsTs(fromHex(v.payload))))).toBe(v.payload);
    });
  }
  for (const v of actions.invalid) {
    it(`rejects ${v.name}`, () => {
      expect(() => decodeActions(fromHex(v.payload))).toThrow();
      expect(() => decodeActionsTs(fromHex(v.payload))).toThrow();
    });
  }
});

describe('golden vectors: keys', () => {
  it('validates the test mnemonic', () => {
    expect(validateMnemonic(keys.mnemonic)).toBe(true);
    expect(validateMnemonic(`  ${keys.mnemonic.toUpperCase()} `)).toBe(true);
    expect(validateMnemonic(keys.mnemonic.replace(/\w+$/, 'abandon'))).toBe(false);
  });
  for (const g of keys.generate_mnemonic) {
    it(`mnemonic from entropy ${g.entropy.slice(0, 8)}…`, () => {
      // entropy with fewer than 12 distinct bytes is refused by generate_mnemonic as a broken-RNG guard
      if (new Set(fromHex(g.entropy)).size < 12) expect(() => getWasm().generate_mnemonic(fromHex(g.entropy))).toThrow(/entropy looks broken/);
      else expect(getWasm().generate_mnemonic(fromHex(g.entropy))).toBe(g.mnemonic);
    });
  }

  it('seed64 is the standard BIP-39 seed (PBKDF2-HMAC-SHA512, 2048 rounds, empty passphrase)', () => {
    expect(toHex(pbkdf2(sha512, utf8(keys.mnemonic), utf8('mnemonic'), { c: 2048, dkLen: 64 }))).toBe(keys.seed64);
    expect(keys.hkdf_salt).toBe('BUNKER/LMS/v1');
  });

  for (const e of keys.epochs) {
    // Independent TypeScript re-computation of MESSAGE_FORMAT §2 from the SDK's binding.
    it(`binding, HKDF info, SEED and I (MESSAGE_FORMAT §2): ${e.name}`, () => {
      const programId = new PublicKey(e.program_id);
      const binding = keyBinding(e.epoch, ctxOf(e, programId));
      expect(toHex(binding)).toBe(e.binding);
      expect(binding.length).toBe(e.epoch === 0 ? (binding[1] === 1 ? 34 : 2) : 32);
      const info = concatBytes(utf8('epoch'), u32le(e.epoch), Uint8Array.of(e.cluster), programId.toBytes(), binding);
      expect(toHex(info)).toBe(e.info);
      const okm = hkdf(sha256, fromHex(keys.seed64), utf8(keys.hkdf_salt), info, 48);
      expect(toHex(okm.subarray(0, 32))).toBe(e.lms_seed);
      expect(toHex(okm.subarray(32, 48))).toBe(e.lms_i);
      expect(e.root.slice(0, 32)).toBe(e.lms_i); // root = I ‖ T1
    });
    it(`derives the root: ${e.name}`, async () => {
      expect(toHex(await deriveRoot(keys.mnemonic, e.epoch, ctxOf(e, new PublicKey(e.program_id))))).toBe(e.root);
    });
  }

  it('open → rotate: the epoch-1 binding is the vault id of the same vault’s epoch-0 root', async () => {
    const epoch1 = keys.epochs.filter((e) => e.epoch === 1);
    expect(epoch1.length).toBeGreaterThan(0);
    for (const e of epoch1) {
      const cluster = clusterName(e.cluster);
      const root0 = await deriveRoot(keys.mnemonic, 0, { cluster }); // these vectors are for vaults without a cosigner
      const vaultId = computeVaultId(root0, null);
      expect(toHex(vaultId)).toBe(e.binding);
      const ctx = vaultKeyContext({ vaultId, cosigner: null }, 1, cluster);
      expect(toHex(await deriveRoot(keys.mnemonic, 1, ctx))).toBe(e.root);
    }
  });

  it('vaultFromSeed gives the golden epoch-0 root, vault id, state and wallet', async () => {
    for (const e of keys.epochs.filter((x) => x.epoch === 0)) {
      const ctx = ctxOf(e);
      const v = await vaultFromSeed(keys.mnemonic, { cluster: ctx.cluster, cosigner: ctx.cosigner ?? null });
      expect(toHex(v.root)).toBe(e.root);
      const golden = vaultIds.vaults.find((x) => x.root === e.root);
      expect(golden, `vault_ids.json has the vault of "${e.name}"`).toBeDefined();
      expect(toHex(v.vaultId)).toBe(golden!.vault_id);
      expect(v.state.toBase58()).toBe(golden!.state);
      expect(v.wallet.toBase58()).toBe(golden!.wallet);
      expect(golden!.options).toBe(e.binding); // epoch-0 binding = the vault's options_v1
    }
  });
});

describe('golden vectors: vault ids and PDAs', () => {
  it('program id matches', () => expect(vaultIds.program_id).toBe(PROGRAM_ID.toBase58()));
  for (const v of vaultIds.vaults) {
    it(v.name, () => {
      const cosigner = v.cosigner ? new PublicKey(v.cosigner) : null;
      const root = fromHex(v.root);
      expect(toHex(encodeOptions(cosigner))).toBe(v.options);
      expect(toHex(getWasm().encode_options(cosigner ? cosigner.toBytes() : new Uint8Array()))).toBe(v.options);
      expect(toHex(computeVaultId(root, cosigner))).toBe(v.vault_id);
      expect(toHex(getWasm().vault_id(root, fromHex(v.options)))).toBe(v.vault_id);
      const [state, bump] = findStatePda(fromHex(v.vault_id));
      expect(state.toBase58()).toBe(v.state);
      expect(bump).toBe(v.state_bump);
      const [wallet, wb] = findWalletPda(state);
      expect(wallet.toBase58()).toBe(v.wallet);
      expect(wb).toBe(v.wallet_bump);
    });
  }
});

describe('golden vectors: messages', () => {
  for (const m of messages.messages) {
    it(m.name, () => {
      const state = new PublicKey(m.vault_state);
      const pid = new PublicKey(m.program_id);
      expect(toHex(messagePrefixTs(m.cluster, m.tag, state, m.root_epoch, m.leaf_index, pid))).toBe(m.prefix);
      const built = getWasm().message(m.cluster, pid.toBytes(), m.tag, state.toBytes(), m.root_epoch, m.leaf_index, fromHex(m.payload));
      expect(toHex(built)).toBe(m.message);
      const parsed = parseMessage(fromHex(m.message));
      expect(parsed).toMatchObject({ clusterId: m.cluster, tag: m.tag, rootEpoch: m.root_epoch, leafIndex: m.leaf_index });
      expect(parsed.state.equals(state)).toBe(true);
      expect(toHex(parsed.payload)).toBe(m.payload);
    });
  }
});

describe('golden vectors: signatures', () => {
  for (const s of signatures.signatures) {
    it(`verifies and re-signs deterministically: ${s.name}`, async () => {
      const w = getWasm();
      const msg = fromHex(s.message);
      const sig = fromHex(s.signature);
      const root = fromHex(s.root);
      const binding = fromHex(s.binding);
      expect(sig.length).toBe(2508);
      expect(w.verify(root, msg, sig)).toBe(true);
      const tampered = msg.slice();
      tampered[tampered.length - 1] = (tampered[tampered.length - 1] as number) ^ 1;
      expect(w.verify(root, tampered, sig)).toBe(false);
      expect(toHex(w.sign(keys.mnemonic, s.epoch, s.leaf_index, msg, binding, root))).toBe(s.signature);

      // The signing key is the vault's key on the message's own deployment: the SDK context for
      // (message cluster, message program, recorded binding) derives the vector root.
      const parsed = parseMessage(msg);
      expect(parsed).toMatchObject({ clusterId: s.cluster, rootEpoch: s.epoch, leafIndex: s.leaf_index });
      const ctx = ctxOf(s, parsed.programId);
      expect(toHex(keyBinding(s.epoch, ctx))).toBe(s.binding);
      expect(toHex(await deriveRoot(keys.mnemonic, s.epoch, ctx))).toBe(s.root);
    });
  }

  it('WASM sign refuses to sign with another vault binding than the expected root’s', () => {
    const w = getWasm();
    const s0 = signatures.signatures.find((x) => x.epoch === 0)!;
    const other0 = encodeOptions(new PublicKey(vaultIds.vaults.find((v) => v.cosigner)!.cosigner!));
    expect(toHex(other0)).not.toBe(s0.binding);
    expect(() => w.sign(keys.mnemonic, s0.epoch, s0.leaf_index, fromHex(s0.message), other0, fromHex(s0.root))).toThrow(/not the expected root/);

    const s1 = signatures.signatures.find((x) => x.epoch >= 1)!;
    const otherVault = fromHex(s1.binding);
    otherVault[0] = (otherVault[0] as number) ^ 1;
    expect(() => w.sign(keys.mnemonic, s1.epoch, s1.leaf_index, fromHex(s1.message), otherVault, fromHex(s1.root))).toThrow(/not the expected root/);
    // A wrong-length expected root is refused before any work.
    expect(() => w.sign(keys.mnemonic, s1.epoch, s1.leaf_index, fromHex(s1.message), fromHex(s1.binding), new Uint8Array(47))).toThrow(/48 bytes/);
  });

  it('WASM sign refuses a leaf/epoch other than the message’s, non-messages and wrong-shaped bindings', () => {
    const w = getWasm();
    const s = signatures.signatures[0]!;
    const msg = fromHex(s.message);
    const binding = fromHex(s.binding);
    const root = fromHex(s.root);
    expect(() => w.sign(keys.mnemonic, s.epoch, s.leaf_index + 1, msg, binding, root)).toThrow(/refusing to sign/);
    expect(() => w.sign(keys.mnemonic, s.epoch + 1, s.leaf_index, msg, new Uint8Array(32), root)).toThrow(/refusing to sign/);
    expect(() => w.sign(keys.mnemonic, s.epoch, s.leaf_index, utf8('hello'), binding, root)).toThrow(/refusing to sign/);
    // epoch 0 takes options_v1, not a vault id
    expect(() => w.sign(keys.mnemonic, s.epoch, s.leaf_index, msg, new Uint8Array(32), root)).toThrow(/binding/);
  });
});
